from decimal import Decimal
from typing import Any


def _numeric_line_no(value: Any) -> Decimal:
    """Apply legacy numeric coercion: a missing or empty value compares as zero."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted ORD_LINE rows and renumber survivors per order."""
    surviving = [
        (str(row.get("ORD_ID", "")), _numeric_line_no(row.get("LINE_NO", "")), index, row)
        for index, row in enumerate(lines)
        if row.get("DEL_FLG", "") != "Y"
    ]
    surviving.sort(key=lambda item: (item[0], item[1], item[2]))

    result: list[dict] = []
    current_order: str | None = None
    new_line_no = 0

    for order_id, _, _, source_row in surviving:
        if order_id != current_order:
            current_order = order_id
            new_line_no = 1
        else:
            new_line_no += 1

        output_row = dict(source_row)
        output_row["LINE_NO"] = new_line_no
        result.append(output_row)

    return result
